import React, { useEffect, useState } from "react";
import axios from "axios";
import { BACKEND_URL } from "../../config";

const Schedule = () => {
  const token = localStorage.getItem("token");
  const user = JSON.parse(localStorage.getItem("user"));
  const isAdmin = user?.role === "Admin";

  const [eventId, setEventId] = useState("");
  const [matches, setMatches] = useState([]);

  const fetchMatches = async () => {
    if (!eventId) return;
    const res = await axios.get(`${BACKEND_URL}/api/schedule/${eventId}`);
    setMatches(res.data);
  };

  useEffect(() => { fetchMatches(); }, [eventId]);

  const updateMatch = async (id, data) => {
    await axios.patch(
      `${BACKEND_URL}/api/schedule/${id}`,
      data,
      { headers: { Authorization: `Bearer ${token}` } }
    );
    fetchMatches();
  };

  const deleteMatch = async (id) => {
    await axios.delete(
      `${BACKEND_URL}/api/schedule/${id}`,
      { headers: { Authorization: `Bearer ${token}` } }
    );
    fetchMatches();
  };

  return (
    <div>
      <h1>Schedule</h1>

      {matches.map(m => (
        <div key={m._id}>
          <b>{m.stage}</b> —
          {m.homeTeam?.teamName || "TBD"} vs {m.awayTeam?.teamName || "TBD"}
          <br />
          {new Date(m.startTime).toDateString()} | {m.timeSlot}

          {isAdmin && (
            <>
              <button onClick={() => updateMatch(m._id, { timeSlot: "Evening" })}>
                Edit
              </button>
              <button onClick={() => deleteMatch(m._id)}>
                Delete
              </button>
            </>
          )}
        </div>
      ))}
    </div>
  );
};

export default Schedule;
